import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static final int ROOT = 3;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= 32 && c != -1);
            while (c > 32 && c != -1) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static int modPow(int a, long e) {
        long result = 1;
        long base = a;
        while (e > 0) {
            if ((e & 1) != 0) result = result * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        return (int) result;
    }

    static void ntt(int[] a, boolean invert) {
        int n = a.length;

        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            while ((j & bit) != 0) {
                j ^= bit;
                bit >>= 1;
            }
            j ^= bit;
            if (i < j) {
                int temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }

        for (int length = 2; length <= n; length <<= 1) {
            int wLen = modPow(ROOT, (MOD - 1L) / length);
            if (invert) wLen = modPow(wLen, MOD - 2L);

            int half = length >> 1;
            for (int i = 0; i < n; i += length) {
                long w = 1;
                for (int j = 0; j < half; j++) {
                    int u = a[i + j];
                    int v = (int) (a[i + j + half] * w % MOD);

                    int x = u + v;
                    if (x >= MOD) x -= MOD;
                    int y = u - v;
                    if (y < 0) y += MOD;

                    a[i + j] = x;
                    a[i + j + half] = y;
                    w = w * wLen % MOD;
                }
            }
        }

        if (invert) {
            int invN = modPow(n, MOD - 2L);
            for (int i = 0; i < n; i++) {
                a[i] = (int) ((long) a[i] * invN % MOD);
            }
        }
    }

    static int[] convolution(int[] a, int[] b) {
        if (a.length == 0 || b.length == 0) return new int[0];

        int resultLength = a.length + b.length - 1;
        if ((long) a.length * b.length <= 256) {
            int[] result = new int[resultLength];
            for (int i = 0; i < a.length; i++) {
                for (int j = 0; j < b.length; j++) {
                    result[i + j] = (int) (
                            (result[i + j] + (long) a[i] * b[j]) % MOD
                    );
                }
            }
            return result;
        }

        int size = 1;
        while (size < resultLength) size <<= 1;

        int[] fa = Arrays.copyOf(a, size);
        int[] fb = Arrays.copyOf(b, size);

        ntt(fa, false);
        ntt(fb, false);
        for (int i = 0; i < size; i++) {
            fa[i] = (int) ((long) fa[i] * fb[i] % MOD);
        }
        ntt(fa, true);

        return Arrays.copyOf(fa, resultLength);
    }

    static int[] trim(int[] a) {
        int length = a.length;
        while (length > 1 && a[length - 1] == 0) length--;
        return length == a.length ? a : Arrays.copyOf(a, length);
    }

    static int[] berlekampMassey(int[] sequence) {
        int max = sequence.length + 2;
        int[] c = new int[max];
        int[] bPoly = new int[max];
        c[0] = 1;
        bPoly[0] = 1;

        int degree = 0;
        int bDegree = 0;
        int shift = 1;
        int lastDiscrepancy = 1;

        for (int pos = 0; pos < sequence.length; pos++) {
            long discrepancy = sequence[pos];
            for (int i = 1; i <= degree; i++) {
                discrepancy += (long) c[i] * sequence[pos - i];
                discrepancy %= MOD;
            }
            int d = (int) discrepancy;

            if (d == 0) {
                shift++;
                continue;
            }

            boolean degreeChanges = 2 * degree <= pos;
            int[] oldC = degreeChanges ? c.clone() : null;
            int oldDegree = degree;

            int coefficient = (int) ((long) d * modPow(lastDiscrepancy, MOD - 2L) % MOD);

            for (int i = 0; i <= bDegree; i++) {
                int index = i + shift;
                long value = c[index] - (long) coefficient * bPoly[i] % MOD;
                if (value < 0) value += MOD;
                c[index] = (int) value;
            }

            if (degreeChanges) {
                degree = pos + 1 - degree;
                bPoly = oldC;
                bDegree = oldDegree;
                lastDiscrepancy = d;
                shift = 1;
            } else {
                shift++;
            }
        }

        int[] recurrence = new int[degree];
        for (int i = 1; i <= degree; i++) {
            recurrence[i - 1] = c[i] == 0 ? 0 : MOD - c[i];
        }
        return recurrence;
    }

    static int linearTerm(int[] initial, int[] recurrence, long index) {
        int degree = recurrence.length;
        if (index < initial.length) return initial[(int) index];

        int[] q = new int[degree + 1];
        q[0] = 1;
        for (int i = 1; i <= degree; i++) {
            q[i] = recurrence[i - 1] == 0 ? 0 : MOD - recurrence[i - 1];
        }

        int[] first = Arrays.copyOf(initial, degree);
        int[] product = convolution(first, q);
        int[] p = Arrays.copyOf(product, degree);
        p = trim(p);
        q = trim(q);

        long n = index;
        while (n > 0) {
            int[] negativeQ = q.clone();
            for (int i = 1; i < negativeQ.length; i += 2) {
                if (negativeQ[i] != 0) negativeQ[i] = MOD - negativeQ[i];
            }

            int[] pq = convolution(p, negativeQ);
            int[] qq = convolution(q, negativeQ);

            int parity = (int) (n & 1);
            int pLength = (pq.length - parity + 1) / 2;
            int[] nextP = new int[Math.max(1, pLength)];
            int at = 0;
            for (int i = parity; i < pq.length; i += 2) {
                nextP[at++] = pq[i];
            }

            int[] nextQ = new int[(qq.length + 1) / 2];
            at = 0;
            for (int i = 0; i < qq.length; i += 2) {
                nextQ[at++] = qq[i];
            }

            p = trim(nextP);
            q = trim(nextQ);
            n >>= 1;
        }

        return (int) ((long) p[0] * modPow(q[0], MOD - 2L) % MOD);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int wordCount = fs.nextInt();
        long targetLength = fs.nextLong();

        String[] words = new String[wordCount];
        int edgeCapacity = 0;
        for (int i = 0; i < wordCount; i++) {
            words[i] = fs.next();
            edgeCapacity += words[i].length();
        }

        int[] edgeFrom = new int[edgeCapacity];
        int[] edgeTo = new int[edgeCapacity];
        char[] edgeChar = new char[edgeCapacity];

        int stateCount = 1;
        int edgeCount = 0;

        for (String word : words) {
            int previous = 0;
            for (int i = 0; i < word.length(); i++) {
                int next;
                if (i == word.length() - 1) {
                    next = 0;
                } else {
                    next = stateCount++;
                }

                edgeFrom[edgeCount] = previous;
                edgeTo[edgeCount] = next;
                edgeChar[edgeCount] = word.charAt(i);
                edgeCount++;

                previous = next;
            }
        }

        int productStates = stateCount * stateCount;
        int maxProductEdges = edgeCount * edgeCount;
        int[] productFrom = new int[maxProductEdges];
        int[] productTo = new int[maxProductEdges];
        int productEdgeCount = 0;

        for (int i = 0; i < edgeCount; i++) {
            for (int j = 0; j < edgeCount; j++) {
                if (edgeChar[i] == edgeChar[j]) {
                    productFrom[productEdgeCount] =
                            edgeFrom[i] * stateCount + edgeFrom[j];
                    productTo[productEdgeCount] =
                            edgeTo[i] * stateCount + edgeTo[j];
                    productEdgeCount++;
                }
            }
        }

        int termCount = 2 * productStates + 5;
        int[] sequence = new int[termCount];
        int[] current = new int[productStates];
        int[] next = new int[productStates];
        current[0] = 1;

        for (int length = 0; length < termCount; length++) {
            sequence[length] = current[0];
            if (length + 1 == termCount) break;

            Arrays.fill(next, 0);
            for (int e = 0; e < productEdgeCount; e++) {
                int value = current[productFrom[e]];
                if (value == 0) continue;

                int destination = productTo[e];
                int sum = next[destination] + value;
                if (sum >= MOD) sum -= MOD;
                next[destination] = sum;
            }

            int[] temp = current;
            current = next;
            next = temp;
        }

        if (targetLength < termCount) {
            System.out.println(sequence[(int) targetLength]);
            return;
        }

        int[] recurrence = berlekampMassey(sequence);
        int answer = linearTerm(sequence, recurrence, targetLength);
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class State {
        int side; // 0 = empty, 1 = top ahead, 2 = bottom ahead
        String residual;

        State(int side, String residual) {
            this.side = side;
            this.residual = residual;
        }
    }

    static class Edge {
        int to;
        int weight;

        Edge(int to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static String key(int side, String residual) {
        return side + "#" + residual;
    }

    static boolean prefixCompatible(String a, String b) {
        int len = Math.min(a.length(), b.length());
        for (int i = 0; i < len; i++) {
            if (a.charAt(i) != b.charAt(i)) return false;
        }
        return true;
    }

    static int getState(
            int side,
            String residual,
            ArrayList<State> states,
            ArrayList<ArrayList<Edge>> graph,
            HashMap<String, Integer> ids
    ) {
        if (side == 0) return 0;
        String key = key(side, residual);
        Integer id = ids.get(key);
        if (id != null) return id;

        int newId = states.size();
        ids.put(key, newId);
        states.add(new State(side, residual));
        graph.add(new ArrayList<>());
        return newId;
    }

    static void addTransition(
            String top,
            String bottom,
            ArrayList<State> states,
            ArrayList<ArrayList<Edge>> graph,
            HashMap<String, Integer> ids,
            int from
    ) {
        if (!prefixCompatible(top, bottom)) return;

        int common = Math.min(top.length(), bottom.length());
        int side;
        String residual;

        if (top.length() == bottom.length()) {
            side = 0;
            residual = "";
        } else if (top.length() > bottom.length()) {
            side = 1;
            residual = top.substring(common);
        } else {
            side = 2;
            residual = bottom.substring(common);
        }

        int to = getState(side, residual, states, graph, ids);
        graph.get(from).add(new Edge(to, common));
    }

    static long modPow(long a, long e) {
        long result = 1;
        while (e > 0) {
            if ((e & 1) != 0) result = result * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return result;
    }

    static long[] berlekampMassey(long[] sequence) {
        ArrayList<Long> c = new ArrayList<>();
        ArrayList<Long> b = new ArrayList<>();
        c.add(1L);
        b.add(1L);

        int length = 0;
        int shift = 1;
        long lastDiscrepancy = 1;

        for (int index = 0; index < sequence.length; index++) {
            long discrepancy = sequence[index];
            for (int i = 1; i <= length; i++) {
                discrepancy = (discrepancy + c.get(i) * sequence[index - i]) % MOD;
            }

            if (discrepancy == 0) {
                shift++;
                continue;
            }

            ArrayList<Long> oldC = new ArrayList<>(c);
            long factor = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD;

            while (c.size() < b.size() + shift) c.add(0L);

            for (int i = 0; i < b.size(); i++) {
                int pos = i + shift;
                long value = (c.get(pos) - factor * b.get(i)) % MOD;
                if (value < 0) value += MOD;
                c.set(pos, value);
            }

            if (2 * length <= index) {
                length = index + 1 - length;
                b = oldC;
                lastDiscrepancy = discrepancy;
                shift = 1;
            } else {
                shift++;
            }
        }

        long[] recurrence = new long[length];
        for (int i = 0; i < length; i++) {
            recurrence[i] = (MOD - c.get(i + 1)) % MOD;
        }
        return recurrence;
    }

    static long[] combine(long[] a, long[] b, long[] recurrence) {
        int k = recurrence.length;
        long[] product = new long[2 * k - 1];

        for (int i = 0; i < k; i++) {
            if (a[i] == 0) continue;
            for (int j = 0; j < k; j++) {
                if (b[j] == 0) continue;
                product[i + j] = (product[i + j] + a[i] * b[j]) % MOD;
            }
        }

        for (int degree = 2 * k - 2; degree >= k; degree--) {
            long value = product[degree];
            if (value == 0) continue;

            for (int j = 0; j < k; j++) {
                int target = degree - 1 - j;
                product[target] = (product[target] + value * recurrence[j]) % MOD;
            }
        }

        return Arrays.copyOf(product, k);
    }

    static long linearRecurrence(long[] initial, long[] recurrence, long index) {
        if (index < initial.length) return initial[(int) index];

        int k = recurrence.length;
        if (k == 0) return 0;

        long[] result = new long[k];
        long[] base = new long[k];
        result[0] = 1;

        if (k == 1) {
            base[0] = recurrence[0];
        } else {
            base[1] = 1;
        }

        long exponent = index;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = combine(result, base, recurrence);
            }
            base = combine(base, base, recurrence);
            exponent >>= 1;
        }

        long answer = 0;
        for (int i = 0; i < k; i++) {
            answer = (answer + result[i] * initial[i]) % MOD;
        }
        return answer;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        long m = fs.nextLong();

        String[] words = new String[n];
        for (int i = 0; i < n; i++) {
            words[i] = fs.next();
        }

        ArrayList<State> states = new ArrayList<>();
        ArrayList<ArrayList<Edge>> graph = new ArrayList<>();
        HashMap<String, Integer> ids = new HashMap<>();

        states.add(new State(0, ""));
        graph.add(new ArrayList<>());
        ids.put(key(0, ""), 0);

        for (int stateId = 0; stateId < states.size(); stateId++) {
            State state = states.get(stateId);

            if (state.side == 0) {
                for (String top : words) {
                    for (String bottom : words) {
                        addTransition(top, bottom, states, graph, ids, stateId);
                    }
                }
            } else if (state.side == 1) {
                for (String bottom : words) {
                    addTransition(state.residual, bottom, states, graph, ids, stateId);
                }
            } else {
                for (String top : words) {
                    addTransition(top, state.residual, states, graph, ids, stateId);
                }
            }
        }

        int stateCount = states.size();
        int recurrenceBound = stateCount * 5;
        int termCount = 2 * recurrenceBound + 10;

        long[][] dp = new long[termCount][stateCount];
        dp[0][0] = 1;

        for (int length = 0; length < termCount; length++) {
            for (int state = 0; state < stateCount; state++) {
                long current = dp[length][state];
                if (current == 0) continue;

                for (Edge edge : graph.get(state)) {
                    int nextLength = length + edge.weight;
                    if (nextLength >= termCount) continue;

                    dp[nextLength][edge.to] += current;
                    if (dp[nextLength][edge.to] >= MOD) {
                        dp[nextLength][edge.to] -= MOD;
                    }
                }
            }
        }

        long[] sequence = new long[termCount];
        for (int i = 0; i < termCount; i++) {
            sequence[i] = dp[i][0];
        }

        if (m < termCount) {
            System.out.println(sequence[(int) m]);
            return;
        }

        long[] recurrence = berlekampMassey(sequence);
        long[] initial = Arrays.copyOf(sequence, recurrence.length);
        System.out.println(linearRecurrence(initial, recurrence, m));
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= 32 && c != -1);
            while (c > 32 && c != -1) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class TrieNode {
        int[] next = new int[26];
        boolean terminal;

        TrieNode() {
            Arrays.fill(next, -1);
        }

        boolean hasChildren() {
            for (int x : next) {
                if (x != -1) return true;
            }
            return false;
        }
    }

    static class Transition {
        int ch;
        int dest;

        Transition(int ch, int dest) {
            this.ch = ch;
            this.dest = dest;
        }
    }

    static long modPow(long a, long e) {
        long result = 1;
        while (e > 0) {
            if ((e & 1) != 0) result = result * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return result;
    }

    static long[] berlekampMassey(long[] sequence) {
        int n = sequence.length;
        long[] c = new long[n + 1];
        long[] bPoly = new long[n + 1];
        c[0] = 1;
        bPoly[0] = 1;

        int length = 0;
        int shift = 1;
        int degreeC = 0;
        int degreeB = 0;
        long lastDiscrepancy = 1;
        long inverseLast = 1;

        for (int pos = 0; pos < n; pos++) {
            long discrepancy = sequence[pos];
            for (int i = 1; i <= length; i++) {
                discrepancy += c[i] * sequence[pos - i] % MOD;
                if (discrepancy >= MOD) discrepancy -= MOD;
            }

            if (discrepancy == 0) {
                shift++;
                continue;
            }

            long coefficient = discrepancy * inverseLast % MOD;
            long[] oldC = c.clone();
            int oldDegreeC = degreeC;

            for (int i = 0; i <= degreeB; i++) {
                int index = i + shift;
                long subtract = coefficient * bPoly[i] % MOD;
                c[index] -= subtract;
                if (c[index] < 0) c[index] += MOD;
                if (c[index] != 0 && index > degreeC) degreeC = index;
            }

            if (2 * length <= pos) {
                length = pos + 1 - length;
                bPoly = oldC;
                degreeB = oldDegreeC;
                lastDiscrepancy = discrepancy;
                inverseLast = modPow(lastDiscrepancy, MOD - 2);
                shift = 1;
            } else {
                shift++;
            }
        }

        long[] recurrence = new long[length];
        for (int i = 0; i < length; i++) {
            recurrence[i] = c[i + 1] == 0 ? 0 : MOD - c[i + 1];
        }
        return recurrence;
    }

    static long[] combine(long[] a, long[] b, long[] recurrence) {
        int k = recurrence.length;
        long[] temp = new long[2 * k - 1];

        for (int i = 0; i < k; i++) {
            if (a[i] == 0) continue;
            for (int j = 0; j < k; j++) {
                if (b[j] == 0) continue;
                int index = i + j;
                temp[index] += a[i] * b[j] % MOD;
                if (temp[index] >= MOD) temp[index] -= MOD;
            }
        }

        for (int degree = 2 * k - 2; degree >= k; degree--) {
            long value = temp[degree];
            if (value == 0) continue;
            for (int j = 0; j < k; j++) {
                int target = degree - 1 - j;
                temp[target] += value * recurrence[j] % MOD;
                if (temp[target] >= MOD) temp[target] -= MOD;
            }
        }

        return Arrays.copyOf(temp, k);
    }

    static long linearRecurrence(long[] initial, long[] recurrence, long index) {
        if (index < initial.length) return initial[(int) index];

        int k = recurrence.length;
        if (k == 0) return 0;

        long[] result = new long[k];
        long[] base = new long[k];
        result[0] = 1;

        if (k == 1) {
            base[0] = recurrence[0];
        } else {
            base[1] = 1;
        }

        long exponent = index;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = combine(result, base, recurrence);
            }
            exponent >>= 1;
            if (exponent > 0) {
                base = combine(base, base, recurrence);
            }
        }

        long answer = 0;
        for (int i = 0; i < k; i++) {
            answer += result[i] * initial[i] % MOD;
            if (answer >= MOD) answer -= MOD;
        }
        return answer;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        long m = fs.nextLong();

        ArrayList<TrieNode> trie = new ArrayList<>();
        trie.add(new TrieNode());

        for (int i = 0; i < n; i++) {
            String word = fs.next();
            int node = 0;
            for (int j = 0; j < word.length(); j++) {
                int ch = word.charAt(j) - 'a';
                if (trie.get(node).next[ch] == -1) {
                    trie.get(node).next[ch] = trie.size();
                    trie.add(new TrieNode());
                }
                node = trie.get(node).next[ch];
            }
            trie.get(node).terminal = true;
        }

        int trieSize = trie.size();
        int[] stateOfNode = new int[trieSize];
        Arrays.fill(stateOfNode, -1);

        int automatonStates = 0;
        for (int i = 0; i < trieSize; i++) {
            if (i == 0 || trie.get(i).hasChildren()) {
                stateOfNode[i] = automatonStates++;
            }
        }

        @SuppressWarnings("unchecked")
        ArrayList<Transition>[] transitions = new ArrayList[automatonStates];
        for (int i = 0; i < automatonStates; i++) {
            transitions[i] = new ArrayList<>();
        }

        int rootState = stateOfNode[0];

        for (int node = 0; node < trieSize; node++) {
            int state = stateOfNode[node];
            if (state == -1) continue;

            TrieNode current = trie.get(node);
            for (int ch = 0; ch < 26; ch++) {
                int child = current.next[ch];
                if (child == -1) continue;

                TrieNode childNode = trie.get(child);
                if (childNode.terminal) {
                    transitions[state].add(new Transition(ch, rootState));
                }
                if (childNode.hasChildren()) {
                    transitions[state].add(new Transition(ch, stateOfNode[child]));
                }
            }
        }

        int pairCapacity = automatonStates * automatonStates;
        int[] pairIndex = new int[pairCapacity];
        Arrays.fill(pairIndex, -1);

        ArrayList<Integer> pairCodes = new ArrayList<>();
        ArrayList<int[]> graph = new ArrayList<>();

        int startCode = rootState * automatonStates + rootState;
        pairIndex[startCode] = 0;
        pairCodes.add(startCode);

        for (int id = 0; id < pairCodes.size(); id++) {
            int code = pairCodes.get(id);
            int firstState = code / automatonStates;
            int secondState = code % automatonStates;

            ArrayList<Integer> destinations = new ArrayList<>();

            for (Transition first : transitions[firstState]) {
                for (Transition second : transitions[secondState]) {
                    if (first.ch != second.ch) continue;

                    int destinationCode =
                            first.dest * automatonStates + second.dest;

                    if (pairIndex[destinationCode] == -1) {
                        pairIndex[destinationCode] = pairCodes.size();
                        pairCodes.add(destinationCode);
                    }
                    destinations.add(pairIndex[destinationCode]);
                }
            }

            int[] edges = new int[destinations.size()];
            for (int i = 0; i < edges.length; i++) {
                edges[i] = destinations.get(i);
            }
            graph.add(edges);
        }

        int states = pairCodes.size();
        int sequenceLength = 2 * states;
        long[] sequence = new long[sequenceLength];

        long[] vector = new long[states];
        vector[0] = 1;

        for (int step = 0; step < sequenceLength; step++) {
            sequence[step] = vector[0];

            long[] nextVector = new long[states];
            for (int state = 0; state < states; state++) {
                long value = vector[state];
                if (value == 0) continue;

                for (int destination : graph.get(state)) {
                    nextVector[destination] += value;
                    if (nextVector[destination] >= MOD) {
                        nextVector[destination] -= MOD;
                    }
                }
            }
            vector = nextVector;
        }

        if (m < sequenceLength) {
            System.out.println(sequence[(int) m]);
            return;
        }

        long[] recurrence = berlekampMassey(sequence);
        long answer = linearRecurrence(sequence, recurrence, m);
        System.out.println(answer);
    }
}

