    static long modPow(long a, long e) {
        long result = 1;
        while (e > 0) {
            if ((e & 1) != 0) result = result * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return result;
    }

    static int[] berlekampMassey(int[] sequence) {
        int n = sequence.length;
        int[] c = new int[n + 1];
        int[] bPoly = new int[n + 1];
        c[0] = 1;
        bPoly[0] = 1;

        int length = 0;
        int shift = 1;
        int lastDiscrepancy = 1;

        for (int pos = 0; pos < n; pos++) {
            long discrepancy = sequence[pos];
            for (int i = 1; i <= length; i++) {
                discrepancy += (long) c[i] * sequence[pos - i];
                discrepancy %= MOD;
            }

            if (discrepancy == 0) {
                shift++;
                continue;
            }

            int[] oldC = c.clone();
            long coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2L) % MOD;

            for (int i = 0; i + shift <= n; i++) {
                if (bPoly[i] == 0) continue;
                long value = c[i + shift] - coefficient * bPoly[i] % MOD;
                if (value < 0) value += MOD;
                c[i + shift] = (int) value;
            }

            if (2 * length <= pos) {
                length = pos + 1 - length;
                bPoly = oldC;
                lastDiscrepancy = (int) discrepancy;
                shift = 1;
            } else {
                shift++;
            }
        }

        int[] recurrence = new int[length];
        for (int i = 0; i < length; i++) {
            recurrence[i] = c[i + 1] == 0 ? 0 : MOD - c[i + 1];
        }
        return recurrence;
    }

    static int[] combine(int[] a, int[] b, int[] recurrence) {
        int k = recurrence.length;
        long[] product = new long[2 * k - 1];

        for (int i = 0; i < k; i++) {
            if (a[i] == 0) continue;
            for (int j = 0; j < k; j++) {
                if (b[j] == 0) continue;
                product[i + j] += (long) a[i] * b[j] % MOD;
                if (product[i + j] >= MOD) product[i + j] -= MOD;
            }
        }

        for (int degree = 2 * k - 2; degree >= k; degree--) {
            long coefficient = product[degree];
            if (coefficient == 0) continue;

            for (int j = 1; j <= k; j++) {
                int index = degree - j;
                product[index] += coefficient * recurrence[j - 1] % MOD;
                if (product[index] >= MOD) product[index] -= MOD;
            }
        }

        int[] result = new int[k];
        for (int i = 0; i < k; i++) result[i] = (int) product[i];
        return result;
    }

    static int linearRecurrenceNth(int[] initial, int[] recurrence, long index) {
        if (index < initial.length) return initial[(int) index];

        int k = recurrence.length;
        if (k == 0) return 0;

        int[] result = new int[k];
        int[] base = new int[k];
        result[0] = 1;

        if (k == 1) {
            base[0] = recurrence[0];
        } else {
            base[1] = 1;
        }

        long exponent = index;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = combine(result, base, recurrence);
            }
            exponent >>= 1;
            if (exponent > 0) {
                base = combine(base, base, recurrence);
            }
        }

        long answer = 0;
        for (int i = 0; i < k; i++) {
            answer += (long) result[i] * initial[i] % MOD;
            if (answer >= MOD) answer -= MOD;
        }
        return (int) answer;
    }

    public static void main(String[] args) throws Exception {
