        ArrayList<Transition>[] transitions = new ArrayList[prefixCount];
        for (int i = 0; i < prefixCount; i++) {
            transitions[i] = new ArrayList<>();
            String prefix = prefixes[i];

            for (int ch = 0; ch < 26; ch++) {
                String next = prefix + (char) ('a' + ch);

                if (dictionary.contains(next)) {
