import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= 32 && c != -1);
            while (c > 32 && c != -1) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class Transition {
        int from, to;
        char ch;

        Transition(int from, int to, char ch) {
            this.from = from;
            this.to = to;
            this.ch = ch;
        }
    }

    static long modPow(long a, long e) {
        long result = 1;
        while (e > 0) {
            if ((e & 1) != 0) result = result * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return result;
    }

    static long[] berlekampMassey(long[] sequence) {
        int n = sequence.length;
        long[] c = new long[n + 1];
        long[] b = new long[n + 1];
        c[0] = 1;
        b[0] = 1;

        int length = 0;
        int shift = 1;
        long lastDiscrepancy = 1;

        for (int pos = 0; pos < n; pos++) {
            long discrepancy = 0;
            for (int i = 0; i <= length; i++) {
                discrepancy += c[i] * sequence[pos - i] % MOD;
                if (discrepancy >= MOD) discrepancy -= MOD;
            }

            if (discrepancy == 0) {
                shift++;
                continue;
            }

            long coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD;
            long[] oldC = c.clone();

            for (int i = 0; i + shift <= n; i++) {
                if (b[i] == 0) continue;
                int j = i + shift;
                long value = c[j] - coefficient * b[i] % MOD;
                if (value < 0) value += MOD;
                c[j] = value;
            }

            if (2 * length <= pos) {
                length = pos + 1 - length;
                b = oldC;
                lastDiscrepancy = discrepancy;
                shift = 1;
            } else {
                shift++;
            }
        }

        long[] recurrence = new long[length];
        for (int i = 0; i < length; i++) {
            recurrence[i] = c[i + 1] == 0 ? 0 : MOD - c[i + 1];
        }
        return recurrence;
    }

    static long[] combine(long[] a, long[] b, long[] recurrence) {
        int length = recurrence.length;
        long[] temp = new long[2 * length - 1];

        for (int i = 0; i < length; i++) {
            if (a[i] == 0) continue;
            for (int j = 0; j < length; j++) {
                if (b[j] == 0) continue;
                temp[i + j] = (temp[i + j] + a[i] * b[j]) % MOD;
            }
        }

        for (int degree = 2 * length - 2; degree >= length; degree--) {
            long value = temp[degree];
            if (value == 0) continue;
            for (int k = 1; k <= length; k++) {
                int target = degree - k;
                temp[target] = (temp[target] + value * recurrence[k - 1]) % MOD;
            }
        }

        return Arrays.copyOf(temp, length);
    }

    static long linearRecurrence(long[] initial, long[] recurrence, long index) {
        int length = recurrence.length;
        if (index < initial.length) return initial[(int) index];
        if (length == 0) return 0;

        long[] result = new long[length];
        long[] base = new long[length];
        result[0] = 1;

        if (length == 1) {
            base[0] = recurrence[0];
        } else {
            base[1] = 1;
        }

        long exponent = index;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = combine(result, base, recurrence);
            }
            exponent >>= 1;
            if (exponent > 0) {
                base = combine(base, base, recurrence);
            }
        }

        long answer = 0;
        for (int i = 0; i < length; i++) {
            answer = (answer + result[i] * initial[i]) % MOD;
        }
        return answer;
    }

    static void bfs(int start, ArrayList<Integer>[] graph, boolean[] visited) {
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        visited[start] = true;
        queue.add(start);

        while (!queue.isEmpty()) {
            int vertex = queue.poll();
            for (int next : graph[vertex]) {
                if (!visited[next]) {
                    visited[next] = true;
                    queue.add(next);
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        long m = fs.nextLong();

        String[] words = new String[n];
        int[][] stateId = new int[n][];
        int baseStates = 1;

        for (int i = 0; i < n; i++) {
            words[i] = fs.next();
            stateId[i] = new int[words[i].length()];
            for (int pos = 1; pos < words[i].length(); pos++) {
                stateId[i][pos] = baseStates++;
            }
        }

        ArrayList<Transition> baseTransitions = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String word = words[i];
            int length = word.length();

            int firstDestination = length == 1 ? 0 : stateId[i][1];
            baseTransitions.add(new Transition(0, firstDestination, word.charAt(0)));

            for (int pos = 1; pos < length; pos++) {
                int destination = pos + 1 == length ? 0 : stateId[i][pos + 1];
                baseTransitions.add(
                        new Transition(stateId[i][pos], destination, word.charAt(pos))
                );
            }
        }

        int productStates = baseStates * baseStates;
        ArrayList<Integer>[] graph = new ArrayList[productStates];
        ArrayList<Integer>[] reverseGraph = new ArrayList[productStates];
        for (int i = 0; i < productStates; i++) {
            graph[i] = new ArrayList<>();
            reverseGraph[i] = new ArrayList<>();
        }

        ArrayList<Integer> edgeFrom = new ArrayList<>();
        ArrayList<Integer> edgeTo = new ArrayList<>();

        for (Transition first : baseTransitions) {
            for (Transition second : baseTransitions) {
                if (first.ch != second.ch) continue;

                int from = first.from * baseStates + second.from;
                int to = first.to * baseStates + second.to;

                edgeFrom.add(from);
                edgeTo.add(to);
                graph[from].add(to);
                reverseGraph[to].add(from);
            }
        }

        boolean[] reachable = new boolean[productStates];
        boolean[] canReachAccept = new boolean[productStates];
        bfs(0, graph, reachable);
        bfs(0, reverseGraph, canReachAccept);

        int[] mapping = new int[productStates];
        Arrays.fill(mapping, -1);
        int reducedStates = 0;

        for (int i = 0; i < productStates; i++) {
            if (reachable[i] && canReachAccept[i]) {
                mapping[i] = reducedStates++;
            }
        }

        int keptEdges = 0;
        for (int i = 0; i < edgeFrom.size(); i++) {
            if (mapping[edgeFrom.get(i)] >= 0 && mapping[edgeTo.get(i)] >= 0) {
                keptEdges++;
            }
        }

        int[] from = new int[keptEdges];
        int[] to = new int[keptEdges];
        int edgeIndex = 0;

        for (int i = 0; i < edgeFrom.size(); i++) {
            int originalFrom = edgeFrom.get(i);
            int originalTo = edgeTo.get(i);
            if (mapping[originalFrom] >= 0 && mapping[originalTo] >= 0) {
                from[edgeIndex] = mapping[originalFrom];
                to[edgeIndex] = mapping[originalTo];
                edgeIndex++;
            }
        }

        int termsCount = Math.max(2, 2 * reducedStates + 2);
        long[] sequence = new long[termsCount];
        long[] current = new long[reducedStates];
        current[mapping[0]] = 1;

        for (int step = 0; step < termsCount; step++) {
            sequence[step] = current[mapping[0]];
            if (step + 1 == termsCount) break;

            long[] next = new long[reducedStates];
            for (int e = 0; e < keptEdges; e++) {
                long value = next[to[e]] + current[from[e]];
                if (value >= MOD) value -= MOD;
                next[to[e]] = value;
            }
            current = next;
        }

        if (m < sequence.length) {
            System.out.println(sequence[(int) m]);
            return;
        }

        long[] recurrence = berlekampMassey(sequence);
        long[] initial = Arrays.copyOf(sequence, recurrence.length);
        System.out.println(linearRecurrence(initial, recurrence, m));
    }
